input.command:
mkdir -p notes
cat > notes/PRC-412.md <<'E'
# PRC-412 調査メモ
- 症状: `bin/price 999` が 900 を返す（期待 899、10% 引き・切り捨て）。
- 原因: f02b252 "price: tidy up rounding" が `$1*90/100` を `($1*90+99)/100`（切り上げ）に変更した。同コミットで同じ式を持つ bin/quote と lib/invoice.sh も切り上げになっている。
- 対応: 3 箇所とも `$1 * 90 / 100` に戻す。テスト（999→899）を先に追加。
E
cat > tests/price_test.sh <<'E'
#!/bin/bash
fail=0
[ "$(bash bin/price 500)" = 450 ] || { echo "price 500"; fail=1; }
[ "$(bash bin/price 1000)" = 900 ] || { echo "price 1000"; fail=1; }
[ "$(bash bin/price 999)" = 899 ] || { echo "price 999"; fail=1; }
[ "$(bash bin/quote 999)" = "quote: 899" ] || { echo "quote 999"; fail=1; }
[ "$(bash lib/invoice.sh 999)" = "member total 899" ] || { echo "invoice 999"; fail=1; }
exit $fail
E
bash scripts/verify.sh
sed -i 's|(\$1 \* 90 + 99) / 100|$1 * 90 / 100|' bin/price bin/quote lib/invoice.sh
bash scripts/verify.sh && echo OK; git diff --stat
